import React from 'react';
import { Helmet } from 'react-helmet';
import Header from '../Components/header';
import Footer from '../Components/Footer';
import Credentials from '../Components/Credentials';
import ContentSidebar from '../Components/ContentSidebar';
import '../Styles/ContentPage.css';
import { BUSINESS, PROFILE_LINKS, localBusinessSchema } from '../data/business';
import { ALL_REVIEWS, reviewByline } from '../data/reviews';

const profiles = [
  { label: 'Read reviews on Google', href: PROFILE_LINKS.google },
  { label: 'See our BBB profile', href: PROFILE_LINKS.bbb },
  { label: 'Visit us on Facebook', href: PROFILE_LINKS.facebook },
  { label: 'See our GAF profile', href: PROFILE_LINKS.gaf },
];

const ReviewsPage: React.FC = () => (
  <>
    <Helmet>
      <title>Customer Reviews | Bravo Roofing LLC</title>
      <meta
        name="description"
        content="Read what Treasure Valley homeowners say about Bravo Roofing LLC, and find our profiles on Google, the BBB, Facebook and GAF."
      />
      <meta property="og:title" content="Customer Reviews | Bravo Roofing LLC" />
      <meta property="og:url" content="https://www.bravoroofingidaho.com/reviews/" />
      <script type="application/ld+json">{JSON.stringify(localBusinessSchema('/reviews/'))}</script>
    </Helmet>

    <Header />

    <main className="cp-page">
      <section className="cp-hero">
        <div className="cp-hero-inner">
          <h1>Bravo Roofing Customer Reviews</h1>
          <p className="cp-lede">
            Here's what homeowners have said about working with us. We also encourage you to read our reviews on other
            sites, so you can see the full picture before you choose a roofer.
          </p>
          <div className="cp-actions">
            <a href={BUSINESS.phoneHref} className="cp-btn cp-btn--primary">Call {BUSINESS.phoneDisplay}</a>
            <a href="/contact/" className="cp-btn cp-btn--ghost">Request a Free Estimate</a>
          </div>
        </div>
      </section>

      <div className="cp-layout">
        <article className="cp-article">
        <section className="cp-section">
          <h2>What our customers say</h2>
          {ALL_REVIEWS.map((review) => (
            <blockquote key={review.author} className="cp-quote">
              “{review.text}”
              <cite>— {reviewByline(review)}</cite>
            </blockquote>
          ))}
        </section>

        <section className="cp-section">
          <h2>Read more reviews, or leave one</h2>
          <p>Worked with us? We'd appreciate your honest feedback. It helps other homeowners in the Treasure Valley.</p>
          <ul className="cp-link-list">
            {profiles.map((profile) => (
              <li key={profile.href}>
                <a href={profile.href} target="_blank" rel="noopener noreferrer">{profile.label}</a>
              </li>
            ))}
          </ul>
        </section>
        </article>

        <ContentSidebar />
      </div>

      <Credentials />
    </main>

    <Footer />
  </>
);

export default ReviewsPage;
